import{_ as e,o,c as t,aa as n}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/academy/img/nastaveni-deniku/05.webp",r="/buildary-help-preview/academy/img/nastaveni-deniku/08.webp",i="/buildary-help-preview/academy/img/nastaveni-deniku/07.webp",m=JSON.parse('{"title":"Nastavit deník","description":"","frontmatter":{"title":"Nastavit deník"},"headers":[],"relativePath":"diary/diarysettings.md","filePath":"diary/diarysettings.md","lastUpdated":1795418046000}'),d={name:"diary/diarysettings.md"};function l(p,a,k,v,u,z){return o(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="nastavit-denik" tabindex="-1">Nastavit deník <a class="header-anchor" href="#nastavit-denik" aria-label="Permalink to &quot;Nastavit deník&quot;">​</a></h1><p>V <strong>Nastavení deníku</strong> určíte pravidla podepisování, pracovní dobu a to, které sekce a pole bude denní záznam obsahovat. Deník nastavte hned po založení, ještě před prvními zápisy.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/nastaveni-deniku">Nastavit deník (podpisy, pracovní doba, sekce)</a> v Akademii.</p><h2 id="kde-nastaveni-najdete" tabindex="-1">Kde nastavení najdete <a class="header-anchor" href="#kde-nastaveni-najdete" aria-label="Permalink to &quot;Kde nastavení najdete&quot;">​</a></h2><p>Nastavení deníku otevřete jedním z těchto způsobů:</p><ul><li>v levém panelu klikněte na <strong>Identifikační údaje</strong> a otevřete záložku <strong>Nastavení deníku</strong>,</li><li>v <strong>Denních záznamech</strong> klikněte na tlačítko <strong>Nastavení deníku</strong> s ikonou ozubeného kola nad časovou lištou,</li><li>v <strong>Seznamu deníků</strong> klikněte na ikonu tužky u deníku a otevřete záložku <strong>Nastavení deníku</strong>.</li></ul><p>Okno má záložku <strong>Základní</strong> a pak jednu záložku pro každou sekci denního záznamu: <strong>Počasí</strong>, <strong>Osoby na staveništi</strong>, <strong>Mechanizmy</strong>, <strong>Materiály, výrobky a technologické dodávky</strong>, <strong>Provedené práce</strong> a <strong>Další záznamy</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Každá záložka se ukládá zvlášť</p><p>Změny na záložce uložte tlačítkem <strong>Uložit</strong> dřív, než přejdete na jinou.</p></div><p>Nastavení deníku smí měnit oprávněná osoba s kompetencí <strong>Administrace deníku</strong>, viz <a href="/buildary-help-preview/diary/userpermissions">Kdo co smí v deníku</a>.</p><h2 id="zakladni" tabindex="-1">Základní <a class="header-anchor" href="#zakladni" aria-label="Permalink to &quot;Základní&quot;">​</a></h2><figure class="shot" style="--w:760px;"><img src="'+s+'" alt="Záložka Základní v Nastavení deníku" loading="lazy"></figure><h3 id="podpisy" tabindex="-1">Podpisy <a class="header-anchor" href="#podpisy" aria-label="Permalink to &quot;Podpisy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pole</th><th>Co určuje</th></tr></thead><tbody><tr><td><strong>Časový limit pro podpis</strong></td><td>Kolik minut zůstane denní záznam nebo Další záznam dočasně zamčený poté, co ho stáhnete k podpisu – viz <a href="/buildary-help-preview/diary/signing#docasny-zamek-a-casovy-limit">Dočasný zámek a časový limit</a>.</td></tr><tr><td><strong>Počet podpisů</strong></td><td>Kolik podpisových polí má podepisovaný Denní protokol. Obvykle podepisuje stavbyvedoucí a technický dozor stavebníka, proto jsou výchozí dvě. Den se uzamkne už prvním podpisem.</td></tr><tr><td><strong>Kontrolovat podpisy Dalších záznamů</strong></td><td>Když je zaškrtnuté <strong>Kontrolovat podpis</strong> (výchozí stav), nejde podepsat a uzamknout den, dokud nejsou podepsané všechny Další záznamy toho dne, které zapsali jiní lidé.</td></tr></tbody></table><p>Jak podepisování probíhá, popisuje <a href="/buildary-help-preview/diary/signing">Podepisování deníku</a>.</p><h3 id="pracovni-doba" tabindex="-1">Pracovní doba <a class="header-anchor" href="#pracovni-doba" aria-label="Permalink to &quot;Pracovní doba&quot;">​</a></h3><ul><li><strong>Pracovní doba</strong> – například 7:00 - 15:30. Text se automaticky vloží do poznámky v sekci Osoby na staveništi, jakmile do ní v daný den zapíšete první záznam. V jednotlivých dnech ho můžete upravit.</li><li><strong>Hodiny pracovního dne</strong> – kolik hodin se předvyplní v poli Hodiny u osob a mechanizmů. Výchozí je 8.</li></ul><h3 id="import-dochazky" tabindex="-1">Import docházky <a class="header-anchor" href="#import-dochazky" aria-label="Permalink to &quot;Import docházky&quot;">​</a></h3><p>Tato část se zobrazí, jen když je na doméně stavby napojený aspoň jeden docházkový systém. Vyberete v ní, ze kterého systému a terminálu se má docházka načítat, a filtrem IČO můžete v denících podzhotovitelů načítat jen osoby daného podzhotovitele. Viz <a href="/buildary-help-preview/diary/attendance_system#vybrat-dochazkovy-system-v-deniku">Docházkový systém</a>.</p><h3 id="poradi-a-zobrazeni-sekci" tabindex="-1">Pořadí a zobrazení sekcí <a class="header-anchor" href="#poradi-a-zobrazeni-sekci" aria-label="Permalink to &quot;Pořadí a zobrazení sekcí&quot;">​</a></h3><p>Šipkami změníte pořadí sekcí v denním záznamu. Volbou <strong>Skrýt</strong> sekci, kterou na stavbě nepotřebujete, z denního záznamu odeberete.</p><h2 id="zalozky-sekci" tabindex="-1">Záložky sekcí <a class="header-anchor" href="#zalozky-sekci" aria-label="Permalink to &quot;Záložky sekcí&quot;">​</a></h2><p>Na záložce každé sekce můžete:</p><ul><li>změnit <strong>Název sekce</strong> – nemá vliv na to, jak sekce funguje,</li><li>změnit <strong>Zkrácený název sekce</strong> – použije se v Denním protokolu a v mobilní aplikaci,</li><li>v části <strong>Nastavení položek sekce</strong> upravit u každého pole název a zkratku a určit, zda se pole zobrazí.</li></ul><table tabindex="0"><thead><tr><th>Volba</th><th>Co znamená</th></tr></thead><tbody><tr><td><strong>Zobrazit</strong></td><td>Pole je v záznamu a jeho vyplnění je dobrovolné.</td></tr><tr><td><strong>Povinné</strong></td><td>Záznam bez vyplněného pole nejde uložit.</td></tr><tr><td><strong>Skrýt</strong></td><td>Pole se v záznamu nezobrazuje.</td></tr></tbody></table><figure class="shot" style="--w:760px;"><img src="'+r+'" alt="Záložka Další záznamy s nastavením položek sekce" loading="lazy"></figure><h3 id="cas-porizeni-zaznamu" tabindex="-1">Čas pořízení záznamu <a class="header-anchor" href="#cas-porizeni-zaznamu" aria-label="Permalink to &quot;Čas pořízení záznamu&quot;">​</a></h3><p>Pole <strong>Čas pořízení záznamu</strong> hlídá zákonnou lhůtu pro zápis do deníku:</p><table tabindex="0"><thead><tr><th>Volba</th><th>Co se zobrazí</th></tr></thead><tbody><tr><td><strong>Skrýt</strong></td><td>Nic.</td></tr><tr><td><strong>Zobrazit</strong></td><td>Datum a čas pořízení, případně poslední změny záznamu.</td></tr><tr><td><strong>Povinné</strong></td><td>Datum a čas a navíc výrazná ikona u záznamů pořízených po zákonné lhůtě, včetně počtu hodin, o které byla lhůta překročena.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Zákonná lhůta</p><p>Lhůta je 48 hodin. Nezapočítávají se do ní dny označené jako nepracovní, nejvýše však dva. Záznamy pořízené nebo upravené po lhůtě mají červenou ikonu s vykřičníkem; když na ni najedete myší, uvidíte datum, čas a počet hodin po lhůtě.</p></div><h2 id="pocasi" tabindex="-1">Počasí <a class="header-anchor" href="#pocasi" aria-label="Permalink to &quot;Počasí&quot;">​</a></h2><figure class="shot" style="--w:760px;"><img src="'+i+'" alt="Záložka Počasí v Nastavení deníku" loading="lazy"></figure><ul><li><strong>Hodiny pro denní zadávání počasí</strong> – celé hodiny, ve kterých se načítají údaje o počasí. Výchozí jsou 06:00, 12:00 a 18:00. Další čas přidáte výběrem ze seznamu, křížkem ho odeberete. V denním záznamu pak vznikne řádek počasí pro každou nastavenou hodinu.</li><li><strong>Siotech čidlo</strong> – ID zařízení, pokud na stavbě používáte teplotní čidlo Siotech. Viz <a href="/buildary-help-preview/diary/sensors">Čidla a odkaz na stavbu</a>.</li></ul><h2 id="provedene-prace" tabindex="-1">Provedené práce <a class="header-anchor" href="#provedene-prace" aria-label="Permalink to &quot;Provedené práce&quot;">​</a></h2><p>Do sekce Provedené práce můžete zapisovat i položky z rozpočtu stavby. Potřebujete k tomu:</p><ol><li>nahraný rozpočet stavby,</li><li>pole <strong>Popis položky</strong> nastavené na <strong>Zobrazit</strong>,</li><li>v poli <strong>Filtrace položek rozpočtu</strong> vybranou celou stavbu nebo její část.</li></ol><p>Jak se pak práce zapisují, popisuje <a href="/buildary-help-preview/diary/dailyentriesworks">Provedené práce</a>.</p><h2 id="dalsi-zaznamy" tabindex="-1">Další záznamy <a class="header-anchor" href="#dalsi-zaznamy" aria-label="Permalink to &quot;Další záznamy&quot;">​</a></h2><p>Kromě polí sekce tu najdete volbu <strong>Zakázat změny pořadí záznamů</strong>, která zabrání měnit pořadí Dalších záznamů.</p><p>U Dalších záznamů a Provedených prací můžete zapnout i tato pole:</p><ul><li><strong>Poloha</strong> – mapa s místem, kterého se záznam týká. Souřadnice se načtou z GPS (v mobilu musí být zapnuté určování polohy) spolu s časem načtení, nebo místo určíte kliknutím do mapy.</li><li><strong>Výkres</strong> – do výkresu umístíte značku v místě, kterého se záznam týká. Výkresy je potřeba nejdřív nahrát do stavby, viz <a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a>.</li></ul><h2 id="stejne-nastaveni-pro-vice-staveb" tabindex="-1">Stejné nastavení pro více staveb <a class="header-anchor" href="#stejne-nastaveni-pro-vice-staveb" aria-label="Permalink to &quot;Stejné nastavení pro více staveb&quot;">​</a></h2><p>Pokud zakládáte hodně staveb, požádejte administrátora domény o <strong>vzorovou stavbu</strong>. Nové stavby z ní převezmou moduly, volbu <strong>Stavba s jedním deníkem</strong>, projektový tým a číselníky – viz <a href="/buildary-help-preview/diary/projectsetup#vzorova-stavba">Vzorová stavba</a>.</p><p>Nový deník na stejné stavbě můžete také založit kopií existujícího deníku a převzít tak jeho nastavení, viz <a href="/buildary-help-preview/diary/diarysetup#novy-denik-nebo-kopie">Založit deník</a>.</p><h2 id="smazat-denik" tabindex="-1">Smazat deník <a class="header-anchor" href="#smazat-denik" aria-label="Permalink to &quot;Smazat deník&quot;">​</a></h2><p>Tlačítko <strong>Smazat deník</strong> je vpravo nahoře v Nastavení deníku. Deník smí smazat oprávněná osoba s kompetencí <strong>Administrace deníku</strong>, a to jen dokud v něm nejsou podepsané a uzamčené dny.</p>',45)])])}const c=e(d,[["render",l]]);export{m as __pageData,c as default};
